import { useCallback, useEffect, useState } from 'react'
import { Badge, Btn, Input, Sel } from '../App'
import * as commercial from '../lib/commercial'

const initialPrice = {
  offeringId: '', amountPounds: '10.00', currency: 'GBP', taxBehaviour: 'provider_calculated', market: 'GB',
  effectiveFrom: '', effectiveTo: '', subscriptionTreatment: 'retain', reason: '',
}
const initialDiscount = {
  name: '', type: 'percentage', value: '10', currency: 'GBP', validFrom: '', validUntil: '',
  totalLimit: '', perCustomerLimit: '1', reason: '',
}

const commercialSections = [
  { id: 'overview', label: 'Overview', description: 'Commercial health, readiness and performance.' },
  { id: 'catalogue', label: 'Catalogue', description: 'Offerings, prices and discount codes.' },
  { id: 'access', label: 'Access', description: 'Entitlements, grants and enforcement.' },
  { id: 'pilots', label: 'Pilots', description: 'Founding pilots and renewal evidence.' },
  { id: 'finance', label: 'Finance', description: 'Platform costs, exports and billing recovery.' },
  { id: 'service', label: 'Service', description: 'Incidents, status and customer notices.' },
  { id: 'support', label: 'Support', description: 'Customer cases and triage.' },
]

function Card({ title, children, hidden = false }) {
  if (hidden) return null
  return <section className="rounded-2xl border border-zinc-800 bg-zinc-900 p-4"><h2 className="font-display text-lg font-bold text-white">{title}</h2><div className="mt-3">{children}</div></section>
}

export default function CommercialAdminPage({ isPlatformAdmin, onBack }) {
  const [activeSection, setActiveSection] = useState('overview')
  const [dashboard, setDashboard] = useState(null)
  const [price, setPrice] = useState(initialPrice)
  const [usageDashboard, setUsageDashboard] = useState({ usageMonths: [], unitEconomics: [] })
  const [usage, setUsage] = useState({ month: '', supabaseDatabaseBytes: '0', supabaseStorageBytes: '0', supabaseEgressBytes: '0', supabaseMau: '0', authenticationEmails: '0', vercelBandwidthBytes: '0', vercelFunctionInvocations: '0', variableCostPounds: '0.00', fixedCostPounds: '0.00', supabaseEvidence: '', vercelEvidence: '', reason: '' })
  const [discount, setDiscount] = useState(initialDiscount)
  const [enforcementReason, setEnforcementReason] = useState('Commercial launch readiness approved')
  const [catalogueAction, setCatalogueAction] = useState({ offeringId: '', code: '', reason: '' })
  const [draftChanges, setDraftChanges] = useState({ trialDays: '0', renewalBehaviour: 'manual', salesChannels: 'web,ios', firstPurchaseOnly: false, noPreviousTrial: false, paymentMethodRequired: false, conversionBehaviour: 'manual', retryDays: '1,3,5', graceDays: '7', graceAccess: 'full', permanentFailure: 'read_only', cancellationTiming: 'end_of_term', partialRefundAccess: 'operator_review', coolingOffDays: '14' })
  const [supportCases, setSupportCases] = useState([])
  const [issuedCode, setIssuedCode] = useState('')
  const [newOffering, setNewOffering] = useState({ code: '', customerType: 'team', billingUnit: 'team_season', billingInterval: 'season', currency: 'GBP', taxBehaviour: 'provider_calculated', renewalBehaviour: 'manual', salesChannels: 'web,ios', reason: '' })
  const [correction, setCorrection] = useState({ entitlementId: '', state: 'active', validUntil: '', reason: '' })
  const [bulkCorrection, setBulkCorrection] = useState({ ids: [], state: 'active', validUntil: '', reason: '', operationId: '', preview: null })
  const [foundingGrant, setFoundingGrant] = useState({ audienceId: '', cycleIds: [], state: 'trial', validFrom: '', validUntil: '', agreedPricePounds: '0.00', discountPounds: '0.00', reason: '', operationId: '', preview: null })
  const [grantAudiences, setGrantAudiences] = useState([])
  const [grantAudience, setGrantAudience] = useState({ name: '', type: 'league', parentAudienceId: '', cycleIds: [], reason: '' })
  const [pilotDashboard, setPilotDashboard] = useState({ pilots: [], feedbackPoints: [], adoption: [] })
  const [pilot, setPilot] = useState({ name: '', leagueName: '', cycleIds: [], startsOn: '', endsOn: '', committeeFeedbackAt: '', captainFeedbackAt: '', reason: '' })
  const [pilotOutcome, setPilotOutcome] = useState({ pilotId: '', renewalOutcome: 'undecided', renewalReasons: '', reason: '' })
  const [incident, setIncident] = useState({ title: '', impact: 'minor', message: '', components: ['web'], reason: '' })
  const [incidentQueue, setIncidentQueue] = useState([])
  const [incidentUpdate, setIncidentUpdate] = useState({ incidentId: '', status: 'identified', message: '', mitigation: '', postIncidentActions: '', notifyAffected: true, reason: '' })
  const [exportPeriod, setExportPeriod] = useState({ from: '', to: '' })
  const [recoveries, setRecoveries] = useState([])
  const [recovery, setRecovery] = useState({ billingCustomerId: '', email: '', evidenceReference: '', reason: '', approvalReason: '' })
  const [status, setStatus] = useState({ loading: true, saving: false, error: '', success: '' })

  const load = useCallback(async () => {
    if (!isPlatformAdmin) return
    setStatus(current => ({ ...current, loading: true, error: '' }))
    try {
      const [next, queue, pendingRecoveries, nextPilotDashboard, nextGrantAudiences, nextIncidentQueue, nextUsageDashboard] = await Promise.all([commercial.getCommercialAdminDashboard(), commercial.getSupportAdminQueue(), commercial.getPendingBillingRecoveries(), commercial.getCommercialPilotDashboard(), commercial.getCommercialGrantAudiences(), commercial.getIncidentAdminQueue(), commercial.getCommercialUsageDashboard()])
      setDashboard(next)
      setSupportCases(queue)
      setRecoveries(pendingRecoveries)
      setPilotDashboard(nextPilotDashboard)
      setGrantAudiences(nextGrantAudiences)
      setIncidentQueue(nextIncidentQueue)
      setUsageDashboard(nextUsageDashboard)
      setPrice(current => ({ ...current, offeringId: current.offeringId || next.offerings?.find(item => item.state === 'published')?.id || '' }))
      setCatalogueAction(current => ({ ...current, offeringId: current.offeringId || next.offerings?.find(item => item.state === 'published')?.id || '' }))
      setStatus(current => ({ ...current, loading: false }))
    } catch (error) {
      setStatus(current => ({ ...current, loading: false, error: error?.message ?? 'Commercial dashboard is unavailable.' }))
    }
  }, [isPlatformAdmin])

  useEffect(() => { load() }, [load])
  if (!isPlatformAdmin) return <Card title="Commercial administration"><p className="text-sm text-red-300">Platform administrator access is required.</p><Btn className="mt-3" variant="ghost" onClick={onBack}>Back</Btn></Card>
  if (status.loading) return <p className="text-sm text-zinc-400">Loading commercial controls…</p>

  const act = async (work, message) => {
    setStatus(current => ({ ...current, saving: true, error: '', success: '' }))
    try { await work(); await load(); setStatus(current => ({ ...current, saving: false, success: message })) }
    catch (error) { setStatus(current => ({ ...current, saving: false, error: error?.message ?? 'The commercial change failed.' })) }
  }
  const metrics = dashboard?.metrics?.[0]
  const enforcementMode = typeof dashboard?.enforcement === 'string'
    ? dashboard.enforcement
    : dashboard?.enforcement?.mode ?? 'observe'
  const currentSection = commercialSections.find(section => section.id === activeSection) ?? commercialSections[0]

  return <div className="space-y-4 pb-8">
    <div className="flex items-start justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-wider text-amber-400">Restricted</p><h1 className="font-display text-2xl font-bold">Commercial operations</h1><p className="mt-1 max-w-xl text-sm text-zinc-400">Manage RooBin's catalogue, customer access and commercial service from focused work areas.</p></div><Btn variant="outline" size="sm" onClick={onBack}>Back to app</Btn></div>
    {status.error && <p role="alert" className="rounded-xl border border-red-900 bg-red-950/50 p-3 text-sm text-red-300">{status.error}</p>}
    {status.success && <p className="rounded-xl border border-emerald-900 bg-emerald-950/50 p-3 text-sm text-emerald-300">{status.success}</p>}

    <nav aria-label="Commercial sections" className="grid grid-cols-2 gap-2 rounded-2xl border border-zinc-800 bg-zinc-950/70 p-2 sm:grid-cols-4 lg:grid-cols-7">
      {commercialSections.map(section => <button key={section.id} type="button" aria-current={activeSection === section.id ? 'page' : undefined} onClick={() => setActiveSection(section.id)} className={`rounded-xl px-3 py-3 text-left transition ${activeSection === section.id ? 'bg-amber-400 text-zinc-950 shadow-lg shadow-amber-950/20' : 'text-zinc-300 hover:bg-zinc-800 hover:text-white'}`}><span className="block text-sm font-bold">{section.label}</span><span className={`mt-1 hidden text-[11px] leading-tight lg:block ${activeSection === section.id ? 'text-zinc-800' : 'text-zinc-500'}`}>{section.description}</span></button>)}
    </nav>

    <div className="rounded-2xl border border-zinc-800 bg-gradient-to-r from-zinc-900 to-zinc-950 p-4">
      <p className="text-xs font-bold uppercase tracking-wider text-amber-400">Current area</p>
      <h2 className="mt-1 font-display text-xl font-bold text-white">{currentSection.label}</h2>
      <p className="mt-1 text-sm text-zinc-400">{currentSection.description}</p>
    </div>

    {activeSection === 'overview' && <div className="grid grid-cols-2 gap-3">
      <Card title="Current month"><p className="text-2xl font-bold text-amber-400">{commercial.formatMoney(metrics?.gross_amount_minor ?? 0)}</p><p className="text-xs text-zinc-400">{metrics?.paid_team_seasons ?? 0} paid team-seasons</p></Card>
      <Card title="Readiness"><p className="text-2xl font-bold text-white">{dashboard?.enforcementGaps?.length ?? 0}</p><p className="text-xs text-zinc-400">uncovered active cycles</p></Card>
    </div>}

    <Card title="What needs attention" hidden={activeSection !== 'overview'}>
      <div className="grid gap-2 sm:grid-cols-3">
        <button type="button" onClick={() => setActiveSection('access')} className="rounded-xl border border-zinc-700 bg-zinc-950 p-3 text-left transition hover:border-amber-500 hover:bg-zinc-800"><span className="block text-2xl font-bold text-white">{dashboard?.enforcementGaps?.length ?? 0}</span><span className="mt-1 block text-sm font-bold text-zinc-200">Access gaps</span><span className="mt-1 block text-xs text-zinc-500">Review grants and enforcement</span></button>
        <button type="button" onClick={() => setActiveSection('catalogue')} className="rounded-xl border border-zinc-700 bg-zinc-950 p-3 text-left transition hover:border-amber-500 hover:bg-zinc-800"><span className="block text-2xl font-bold text-white">{dashboard?.prices?.filter(item => item.state === 'published' && !item.provider_price_refs?.stripe).length ?? 0}</span><span className="mt-1 block text-sm font-bold text-zinc-200">Unbound prices</span><span className="mt-1 block text-xs text-zinc-500">Connect published prices to Stripe</span></button>
        <button type="button" onClick={() => setActiveSection('support')} className="rounded-xl border border-zinc-700 bg-zinc-950 p-3 text-left transition hover:border-amber-500 hover:bg-zinc-800"><span className="block text-2xl font-bold text-white">{dashboard?.support?.openCases ?? 0}</span><span className="mt-1 block text-sm font-bold text-zinc-200">Open cases</span><span className="mt-1 block text-xs text-zinc-500">Triage customer support</span></button>
      </div>
    </Card>

    <Card title="Monthly platform usage and unit economics" hidden={activeSection !== 'finance'}>
      <p className="mb-2 text-xs text-zinc-400">Record invoice/console totals once per month. Byte fields use provider-reported bytes; costs are entered in pounds. Evidence stores references, never secrets.</p><div className="grid grid-cols-2 gap-2"><Input label="Month" type="month" value={usage.month} onChange={event=>setUsage({...usage,month:event.target.value})}/><Input label="Supabase database bytes" type="number" min="0" value={usage.supabaseDatabaseBytes} onChange={event=>setUsage({...usage,supabaseDatabaseBytes:event.target.value})}/><Input label="Supabase storage bytes" type="number" min="0" value={usage.supabaseStorageBytes} onChange={event=>setUsage({...usage,supabaseStorageBytes:event.target.value})}/><Input label="Supabase egress bytes" type="number" min="0" value={usage.supabaseEgressBytes} onChange={event=>setUsage({...usage,supabaseEgressBytes:event.target.value})}/><Input label="Supabase MAU" type="number" min="0" value={usage.supabaseMau} onChange={event=>setUsage({...usage,supabaseMau:event.target.value})}/><Input label="Authentication emails" type="number" min="0" value={usage.authenticationEmails} onChange={event=>setUsage({...usage,authenticationEmails:event.target.value})}/><Input label="Vercel bandwidth bytes" type="number" min="0" value={usage.vercelBandwidthBytes} onChange={event=>setUsage({...usage,vercelBandwidthBytes:event.target.value})}/><Input label="Vercel function invocations" type="number" min="0" value={usage.vercelFunctionInvocations} onChange={event=>setUsage({...usage,vercelFunctionInvocations:event.target.value})}/><Input label="Variable cost £" type="number" min="0" step="0.01" value={usage.variableCostPounds} onChange={event=>setUsage({...usage,variableCostPounds:event.target.value})}/><Input label="Fixed cost £" type="number" min="0" step="0.01" value={usage.fixedCostPounds} onChange={event=>setUsage({...usage,fixedCostPounds:event.target.value})}/></div><Input label="Supabase evidence reference" value={usage.supabaseEvidence} onChange={event=>setUsage({...usage,supabaseEvidence:event.target.value})}/><Input label="Vercel evidence reference" value={usage.vercelEvidence} onChange={event=>setUsage({...usage,vercelEvidence:event.target.value})}/><Input label="Recording reason" value={usage.reason} onChange={event=>setUsage({...usage,reason:event.target.value})}/><Btn size="sm" disabled={status.saving||!usage.month||usage.reason.trim().length<8||!usage.supabaseEvidence.trim()||!usage.vercelEvidence.trim()} onClick={()=>act(()=>commercial.recordCommercialPlatformUsage(usage),'Monthly usage, costs and evidence recorded and audited.')}>Record monthly snapshot</Btn>
      <div className="mt-3 space-y-2">{usageDashboard.unitEconomics.slice(0,6).map(item=><div key={item.month} className="rounded-lg bg-zinc-800 p-2 text-xs"><strong>{new Date(item.month).toLocaleDateString('en-GB',{month:'long',year:'numeric'})}</strong> · platform cost {commercial.formatMoney(item.platform_cost_minor)} · {item.paid_team_seasons} paid team-seasons · cost per paid team-season {item.cost_per_paid_team_season_minor==null?'not available':commercial.formatMoney(Number(item.cost_per_paid_team_season_minor))}</div>)}</div>
    </Card>

    <Card title="Entitlement enforcement" hidden={activeSection !== 'access'}>
      <div className="flex flex-wrap items-center gap-2"><Badge color={enforcementMode === 'enforce' ? 'green' : 'amber'}>{enforcementMode}</Badge><span className="text-xs text-zinc-400">Enforce cannot be enabled while readiness gaps remain.</span></div>
      <Input label="Approval reason" value={enforcementReason} onChange={event => setEnforcementReason(event.target.value)} />
      <div className="flex gap-2"><Btn size="sm" variant="outline" disabled={status.saving} onClick={() => act(() => commercial.setCommercialEnforcement('observe', enforcementReason), 'Observe mode enabled.')}>Observe</Btn><Btn size="sm" disabled={status.saving || dashboard?.enforcementGaps?.length > 0} onClick={() => act(() => commercial.setCommercialEnforcement('enforce', enforcementReason), 'Enforcement enabled.')}>Enforce</Btn></div>
    </Card>

    <Card title="Schedule price" hidden={activeSection !== 'catalogue'}>
      <Sel label="Offering" value={price.offeringId} onChange={event => setPrice({ ...price, offeringId: event.target.value })}>{dashboard?.offerings?.map(item => <option key={item.id} value={item.id}>{item.code} v{item.version} ({item.state})</option>)}</Sel>
      <div className="grid grid-cols-2 gap-2"><Input label="Price in pounds" type="number" min="0" step="0.01" value={price.amountPounds} onChange={event => setPrice({ ...price, amountPounds: event.target.value })}/><Input label="Effective from" type="datetime-local" value={price.effectiveFrom} onChange={event => setPrice({ ...price, effectiveFrom: event.target.value })}/></div>
      <Sel label="Existing purchases" value={price.subscriptionTreatment} onChange={event => setPrice({ ...price, subscriptionTreatment: event.target.value })}><option value="retain">Retain agreed price</option><option value="migrate_at_renewal">Change at renewal</option><option value="require_acceptance">Require acceptance</option></Sel>
      <Input label="Approval reason" value={price.reason} onChange={event => setPrice({ ...price, reason: event.target.value })}/>
      <Btn size="sm" disabled={status.saving || !price.offeringId || !price.effectiveFrom || price.reason.trim().length < 8} onClick={() => act(() => commercial.scheduleCommercialPrice(price), 'Price scheduled and audited.')}>Schedule price</Btn>
      <div className="mt-4 border-t border-zinc-800 pt-3"><p className="text-xs text-zinc-400">Provider preview: published prices below are what public pricing and checkout resolve by effective date. Bind once to create the matching immutable Stripe price.</p>{dashboard?.prices?.filter(item => item.state === 'published').slice(0,8).map(item => <div key={item.id} className="mt-2 flex flex-wrap items-center justify-between gap-2 rounded-lg bg-zinc-800 p-2 text-xs"><span>{commercial.formatMoney(item.amount_minor,item.currency)} · {new Date(item.effective_from).toLocaleDateString('en-GB')} · {item.provider_price_refs?.stripe ? 'Stripe ready' : 'Stripe unbound'}</span>{!item.provider_price_refs?.stripe && <Btn size="sm" variant="outline" disabled={status.saving || price.reason.trim().length < 8} onClick={() => act(() => commercial.bindStripeCataloguePrice(item.id,price.reason), 'Stripe price created and audited against this version.')}>Create Stripe price</Btn>}</div>)}</div>
    </Card>

    <Card title="Offering lifecycle" hidden={activeSection !== 'catalogue'}>
      <Sel label="Offering" value={catalogueAction.offeringId} onChange={event => setCatalogueAction({ ...catalogueAction, offeringId: event.target.value })}>{dashboard?.offerings?.map(item => <option key={item.id} value={item.id}>{item.code} v{item.version} ({item.state})</option>)}</Sel>
      <Input label="New code (clone only)" placeholder="team-season-next" value={catalogueAction.code} onChange={event => setCatalogueAction({ ...catalogueAction, code: event.target.value.toLowerCase() })}/>
      <Input label="Approval/change reason" value={catalogueAction.reason} onChange={event => setCatalogueAction({ ...catalogueAction, reason: event.target.value })}/>
      <div className="flex flex-wrap gap-2"><Btn size="sm" variant="outline" disabled={status.saving || !catalogueAction.code || catalogueAction.reason.trim().length < 8} onClick={() => act(() => commercial.cloneCommercialOffering(catalogueAction.offeringId, catalogueAction.code, catalogueAction.reason), 'Draft offering cloned.')}>Clone draft</Btn><Btn size="sm" disabled={status.saving || catalogueAction.reason.trim().length < 8 || dashboard?.offerings?.find(item => item.id === catalogueAction.offeringId)?.state !== 'draft'} onClick={() => act(() => commercial.publishCommercialOffering(catalogueAction.offeringId, catalogueAction.reason), 'Offering published.')}>Publish draft</Btn><Btn size="sm" variant="danger" disabled={status.saving || catalogueAction.reason.trim().length < 8 || dashboard?.offerings?.find(item => item.id === catalogueAction.offeringId)?.state !== 'published'} onClick={() => act(() => commercial.retireCommercialOffering(catalogueAction.offeringId, catalogueAction.reason), 'Offering retired for new sales.')}>Retire</Btn></div>
      {dashboard?.offerings?.find(item => item.id === catalogueAction.offeringId)?.state === 'draft' && <div className="mt-4 border-t border-zinc-800 pt-4"><h3 className="font-bold">Draft eligibility, recovery and refund policy</h3><div className="mt-2 grid grid-cols-2 gap-2"><Input label="Trial days" type="number" min="0" value={draftChanges.trialDays} onChange={event => setDraftChanges({ ...draftChanges, trialDays: event.target.value })}/><Sel label="Renewal" value={draftChanges.renewalBehaviour} onChange={event => setDraftChanges({ ...draftChanges, renewalBehaviour: event.target.value })}><option value="manual">Manual</option><option value="automatic">Automatic</option></Sel></div><Input label="Sales channels" value={draftChanges.salesChannels} onChange={event => setDraftChanges({ ...draftChanges, salesChannels: event.target.value })}/><div className="grid gap-2 text-sm text-zinc-300 sm:grid-cols-2">{[['firstPurchaseOnly','First purchase only'],['noPreviousTrial','Block repeat trials'],['paymentMethodRequired','Payment method required']].map(([key,label]) => <label key={key} className="flex items-center gap-2"><input type="checkbox" checked={draftChanges[key]} onChange={event => setDraftChanges({ ...draftChanges, [key]: event.target.checked })}/>{label}</label>)}</div><div className="mt-2 grid grid-cols-2 gap-2"><Input label="Retry days" value={draftChanges.retryDays} onChange={event => setDraftChanges({ ...draftChanges,retryDays:event.target.value })}/><Input label="Grace days" type="number" min="0" max="30" value={draftChanges.graceDays} onChange={event => setDraftChanges({ ...draftChanges,graceDays:event.target.value })}/><Sel label="Grace access" value={draftChanges.graceAccess} onChange={event => setDraftChanges({ ...draftChanges,graceAccess:event.target.value })}><option value="full">Full during grace</option><option value="read_only">Read only</option></Sel><Sel label="Permanent failure" value={draftChanges.permanentFailure} onChange={event => setDraftChanges({ ...draftChanges,permanentFailure:event.target.value })}><option value="read_only">Read only</option><option value="suspend">Suspend</option></Sel><Sel label="Cancellation timing" value={draftChanges.cancellationTiming} onChange={event => setDraftChanges({ ...draftChanges,cancellationTiming:event.target.value })}><option value="end_of_term">End of term</option><option value="immediate">Immediate</option></Sel><Sel label="Partial refund access" value={draftChanges.partialRefundAccess} onChange={event => setDraftChanges({ ...draftChanges,partialRefundAccess:event.target.value })}><option value="operator_review">Operator review</option><option value="retain_until_end">Retain until end</option><option value="end_immediately">End immediately</option></Sel><Input label="Cooling-off days" type="number" min="0" max="30" value={draftChanges.coolingOffDays} onChange={event => setDraftChanges({ ...draftChanges,coolingOffDays:event.target.value })}/></div><Btn className="mt-3" size="sm" variant="outline" disabled={status.saving || catalogueAction.reason.trim().length < 8} onClick={() => act(() => Promise.all([commercial.updateDraftCommercialOffering(catalogueAction.offeringId, { trialDays: Number(draftChanges.trialDays), renewalBehaviour: draftChanges.renewalBehaviour, salesChannels: draftChanges.salesChannels.split(',').map(value => value.trim()).filter(Boolean), eligibility: { firstPurchaseOnly: draftChanges.firstPurchaseOnly, noPreviousTrial: draftChanges.noPreviousTrial, paymentMethodRequired: draftChanges.paymentMethodRequired, conversionBehaviour: draftChanges.conversionBehaviour } }, catalogueAction.reason),commercial.updateDraftCommercialRecoveryPolicy(catalogueAction.offeringId,{ retryDays:draftChanges.retryDays.split(',').map(Number).filter(value => value > 0), graceDays:Number(draftChanges.graceDays), graceAccess:draftChanges.graceAccess, permanentFailure:draftChanges.permanentFailure },catalogueAction.reason),commercial.updateDraftCommercialRefundPolicy(catalogueAction.offeringId,{ cancellationTiming:draftChanges.cancellationTiming,partialRefundAccess:draftChanges.partialRefundAccess,coolingOffDays:Number(draftChanges.coolingOffDays),immediateCancellationRequiresRefund:true },catalogueAction.reason)]), 'Draft eligibility, recovery and refund policy updated and audited.')}>Save draft rules</Btn></div>}
    </Card>

    <Card title="Create offering draft" hidden={activeSection !== 'catalogue'}>
      <Input label="Offering code" placeholder="team-year-standard" value={newOffering.code} onChange={event => setNewOffering({ ...newOffering, code: event.target.value.toLowerCase() })}/><div className="grid grid-cols-2 gap-2"><Sel label="Billing unit" value={newOffering.billingUnit} onChange={event => setNewOffering({ ...newOffering, billingUnit: event.target.value })}><option value="team_season">Team season</option><option value="team_year">Team year</option><option value="organisation_year">Organisation year</option><option value="venue_year">Venue year</option><option value="league_team_quantity">League team quantity</option></Sel><Sel label="Interval" value={newOffering.billingInterval} onChange={event => setNewOffering({ ...newOffering, billingInterval: event.target.value })}><option value="season">Season</option><option value="one_time">One time</option><option value="month">Month</option><option value="year">Year</option></Sel></div><Input label="Sales channels" value={newOffering.salesChannels} onChange={event => setNewOffering({ ...newOffering, salesChannels: event.target.value })}/><Input label="Creation reason" value={newOffering.reason} onChange={event => setNewOffering({ ...newOffering, reason: event.target.value })}/><Btn size="sm" disabled={status.saving || newOffering.code.length < 3 || newOffering.reason.trim().length < 8 || !dashboard?.products?.length || !dashboard?.entitlementDefinitions?.length} onClick={() => act(() => commercial.createCommercialOfferingDraft({ ...newOffering, productId: dashboard.products[0].id, entitlementDefinitionId: dashboard.entitlementDefinitions.find(item => item.state === 'published')?.id, salesChannels: newOffering.salesChannels.split(',').map(value => value.trim()).filter(Boolean), minQuantity: 1, trialDays: 0, eligibility: {} }, newOffering.reason), 'Offering draft created. Schedule its price before publication.')}>Create draft</Btn>
    </Card>

    <Card title="Publish discount" hidden={activeSection !== 'catalogue'}>
      <Input label="Discount name" value={discount.name} onChange={event => setDiscount({ ...discount, name: event.target.value })}/>
      <div className="grid grid-cols-2 gap-2"><Sel label="Type" value={discount.type} onChange={event => setDiscount({ ...discount, type: event.target.value })}><option value="percentage">Percentage</option><option value="fixed">Fixed pounds</option></Sel><Input label={discount.type === 'percentage' ? 'Percent' : 'Pounds'} type="number" min="0" step={discount.type === 'percentage' ? '1' : '0.01'} value={discount.value} onChange={event => setDiscount({ ...discount, value: event.target.value })}/></div>
      <div className="grid grid-cols-2 gap-2"><Input label="Valid from" type="datetime-local" value={discount.validFrom} onChange={event => setDiscount({ ...discount, validFrom: event.target.value })}/><Input label="Valid until" type="datetime-local" value={discount.validUntil} onChange={event => setDiscount({ ...discount, validUntil: event.target.value })}/></div>
      <Input label="Approval reason" value={discount.reason} onChange={event => setDiscount({ ...discount, reason: event.target.value })}/>
      <Btn size="sm" disabled={status.saving || !discount.validFrom || discount.name.trim().length < 3 || discount.reason.trim().length < 8} onClick={() => act(() => commercial.createCommercialDiscount({ ...discount, value: discount.type === 'fixed' ? Number(discount.value) * 100 : discount.value }), 'Discount published and audited.')}>Publish discount</Btn>
      {dashboard?.discounts?.filter(item => item.state === 'published').map(item => <div key={item.id} className="mt-3 flex flex-wrap items-center justify-between gap-2 rounded-lg bg-zinc-800 p-3"><span className="text-sm font-bold">{item.name}</span><Btn size="sm" variant="outline" disabled={status.saving} onClick={() => act(async () => { const result = await commercial.issueCommercialDiscountCode(item.id, `Issue single use code for ${item.name}`); setIssuedCode(result.code) }, 'Single-use Stripe promotion code issued. Copy it now.')}>Issue code</Btn></div>)}
      {issuedCode && <div className="mt-3 rounded-lg border border-amber-700 bg-amber-950/30 p-3"><p className="text-xs text-zinc-400">Shown once — copy this code now</p><p className="mt-1 font-mono text-lg font-bold text-amber-300">{issuedCode}</p></div>}
    </Card>

    <Card title="Reconciliation and support" hidden={activeSection !== 'overview'}>
      <div className="grid grid-cols-3 gap-3 text-sm"><div><p className="text-2xl font-bold">{dashboard?.reconciliationIssues?.length ?? 0}</p><p className="text-zinc-400">payment issues</p></div><div><p className="text-2xl font-bold">{dashboard?.support?.openCases ?? 0}</p><p className="text-zinc-400">open support cases</p></div><div><p className={`text-2xl font-bold ${(dashboard?.notifications?.failed??0)>0?'text-red-400':''}`}>{dashboard?.notifications?.failed ?? 0}</p><p className="text-zinc-400">failed notices</p></div></div>
      {(dashboard?.reconciliationIssues?.length > 0 || dashboard?.enforcementGaps?.length > 0) && <div className="mt-3 space-y-2">{dashboard.reconciliationIssues?.slice(0, 10).map(item => <p key={`${item.issue_type}-${item.entity_id}`} className="rounded-lg bg-zinc-800 p-2 text-xs text-zinc-300">{item.issue_type}: {item.entity_id}</p>)}{dashboard.enforcementGaps?.slice(0, 10).map(item => <p key={item.playing_cycle_id} className="rounded-lg bg-zinc-800 p-2 text-xs text-zinc-300">Access gap: {item.name}</p>)}</div>}
    </Card>
    <Card title="Offering performance" hidden={activeSection !== 'overview'}>
      <div className="overflow-x-auto"><table className="w-full text-left text-xs"><thead className="text-zinc-400"><tr><th className="p-2">Offering</th><th className="p-2">Purchases</th><th className="p-2">Active</th><th className="p-2">Renewed</th><th className="p-2">Cancelled</th><th className="p-2">Discount</th><th className="p-2">Gross</th></tr></thead><tbody>{dashboard?.offeringPerformance?.map(item => <tr key={item.offering_id} className="border-t border-zinc-800"><td className="p-2">{item.code} v{item.version}</td><td className="p-2">{item.purchases}</td><td className="p-2">{item.active_subscriptions}</td><td className="p-2">{item.renewed_subscriptions}</td><td className="p-2">{item.cancellations} ({item.cancellation_rate_percent}%)</td><td className="p-2">{commercial.formatMoney(item.gross_discount_minor)}</td><td className="p-2">{commercial.formatMoney(item.gross_revenue_minor)}</td></tr>)}</tbody></table></div>
    </Card>
    <Card title="Controlled access correction" hidden={activeSection !== 'access'}>
      <Sel label="Entitlement" value={correction.entitlementId} onChange={event => setCorrection({ ...correction, entitlementId: event.target.value })}><option value="">Select an entitlement</option>{dashboard?.correctionCandidates?.map(item => <option key={item.id} value={item.id}>{item.teamName} / {item.cycleName} ({item.state})</option>)}</Sel><div className="grid grid-cols-2 gap-2"><Sel label="Correct state" value={correction.state} onChange={event => setCorrection({ ...correction, state: event.target.value })}>{['active','trial','grace','expired','revoked','cancelled','refunded','complimentary'].map(value => <option key={value}>{value}</option>)}</Sel><Input label="Valid until (optional)" type="datetime-local" value={correction.validUntil} onChange={event => setCorrection({ ...correction, validUntil: event.target.value })}/></div><Input label="Detailed correction reason" value={correction.reason} onChange={event => setCorrection({ ...correction, reason: event.target.value })}/><Btn size="sm" variant="danger" disabled={status.saving || !correction.entitlementId || correction.reason.trim().length < 12} onClick={() => act(() => commercial.correctTeamCycleAccess(correction.entitlementId, correction.state, correction.validUntil, correction.reason), 'Entitlement correction applied and audited.')}>Apply correction</Btn>
    </Card>
    <Card title="Bulk access correction" hidden={activeSection !== 'access'}>
      <p className="mb-2 text-xs text-zinc-400">Select up to 100 records. Preview is mandatory and any changed selection invalidates confirmation.</p>
      <div className="max-h-48 space-y-1 overflow-auto rounded-lg bg-zinc-950 p-2">{dashboard?.correctionCandidates?.map(item => <label key={item.id} className="flex items-center gap-2 text-sm"><input type="checkbox" checked={bulkCorrection.ids.includes(item.id)} onChange={event => setBulkCorrection(current => ({ ...current, ids: event.target.checked ? [...current.ids,item.id] : current.ids.filter(id => id !== item.id), preview: null, operationId: '' }))}/>{item.teamName} / {item.cycleName} ({item.state})</label>)}</div>
      <Sel label="Correct state" value={bulkCorrection.state} onChange={event => setBulkCorrection({ ...bulkCorrection, state: event.target.value, preview: null, operationId: '' })}>{['active','trial','grace','expired','revoked','cancelled','refunded','complimentary'].map(value => <option key={value}>{value}</option>)}</Sel><Input label="Valid until (optional)" type="datetime-local" value={bulkCorrection.validUntil} onChange={event => setBulkCorrection({ ...bulkCorrection, validUntil: event.target.value, preview: null, operationId: '' })}/><Input label="Detailed correction reason" value={bulkCorrection.reason} onChange={event => setBulkCorrection({ ...bulkCorrection, reason: event.target.value, preview: null, operationId: '' })}/>
      <div className="flex gap-2"><Btn size="sm" variant="outline" disabled={status.saving || bulkCorrection.ids.length < 1 || bulkCorrection.ids.length > 100 || bulkCorrection.reason.trim().length < 12} onClick={async () => { const operationId = crypto.randomUUID(); try { const preview = await commercial.correctTeamCycleAccessBatch(operationId, bulkCorrection.ids, bulkCorrection.state, bulkCorrection.validUntil, bulkCorrection.reason, true); setBulkCorrection(current => ({ ...current, operationId, preview })) } catch (error) { setStatus(current => ({ ...current, error: error?.message ?? 'Correction preview failed.' })) } }}>Preview {bulkCorrection.ids.length} changes</Btn><Btn size="sm" variant="danger" disabled={status.saving || !bulkCorrection.preview || bulkCorrection.preview.count !== bulkCorrection.ids.length} onClick={() => act(() => commercial.correctTeamCycleAccessBatch(bulkCorrection.operationId, bulkCorrection.ids, bulkCorrection.state, bulkCorrection.validUntil, bulkCorrection.reason, false), `${bulkCorrection.ids.length} entitlement corrections applied and audited.`)}>Confirm previewed batch</Btn></div>
      {bulkCorrection.preview && <p className="mt-2 rounded-lg border border-amber-800 bg-amber-950/30 p-2 text-sm text-amber-200">Preview ready: {bulkCorrection.preview.count} entitlements will change to {bulkCorrection.state}. Confirm only after reviewing the selected records.</p>}
    </Card>
    <Card title="Founding league and division audiences" hidden={activeSection !== 'access'}>
      <p className="mb-2 text-xs text-zinc-400">Save the complete team-cycle roster for a league or a selected division. Membership changes are audited, and confirmation is rejected if the audience changed after preview.</p><div className="grid grid-cols-2 gap-2"><Input label="Audience name" value={grantAudience.name} onChange={event=>setGrantAudience({...grantAudience,name:event.target.value})}/><Sel label="Audience type" value={grantAudience.type} onChange={event=>setGrantAudience({...grantAudience,type:event.target.value,parentAudienceId:''})}><option value="league">Whole league</option><option value="division">Division</option></Sel></div>{grantAudience.type==='division'&&<Sel label="Parent league" value={grantAudience.parentAudienceId} onChange={event=>setGrantAudience({...grantAudience,parentAudienceId:event.target.value})}><option value="">Select league</option>{grantAudiences.filter(item=>item.audienceType==='league').map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</Sel>}<div className="max-h-40 space-y-1 overflow-auto rounded-lg bg-zinc-950 p-2">{dashboard?.enforcementGaps?.map(item=><label key={item.playing_cycle_id} className="flex items-center gap-2 text-xs"><input type="checkbox" checked={grantAudience.cycleIds.includes(item.playing_cycle_id)} onChange={event=>setGrantAudience(current=>({...current,cycleIds:event.target.checked?[...current.cycleIds,item.playing_cycle_id]:current.cycleIds.filter(id=>id!==item.playing_cycle_id)}))}/>{item.team_name} / {item.name}</label>)}</div><Input label="Roster approval reason" value={grantAudience.reason} onChange={event=>setGrantAudience({...grantAudience,reason:event.target.value})}/><Btn size="sm" disabled={status.saving||grantAudience.name.trim().length<3||!grantAudience.cycleIds.length||(grantAudience.type==='division'&&!grantAudience.parentAudienceId)||grantAudience.reason.trim().length<12} onClick={()=>act(()=>commercial.saveCommercialGrantAudience(grantAudience),`${grantAudience.type==='league'?'League':'Division'} grant audience saved and audited.`)}>Save audience</Btn>
      <div className="mt-3 space-y-1">{grantAudiences.map(item=><p key={item.id} className="rounded-lg bg-zinc-800 p-2 text-xs"><strong>{item.name}</strong> · {item.audienceType} · {item.playingCycleIds?.length??0} team cycles</p>)}</div>
    </Card>
    <Card title="Founding trial or complimentary grant" hidden={activeSection !== 'access'}>
      <p className="mb-2 text-xs text-zinc-400">Choose a saved whole league/division audience, or select individual uncovered team cycles. Preview is mandatory.</p><Sel label="Saved audience (optional)" value={foundingGrant.audienceId} onChange={event=>setFoundingGrant({...foundingGrant,audienceId:event.target.value,cycleIds:[],preview:null,operationId:''})}><option value="">Individual team selection</option>{grantAudiences.map(item=><option key={item.id} value={item.id}>{item.name} ({item.audienceType}, {item.playingCycleIds?.length??0})</option>)}</Sel>{!foundingGrant.audienceId&&<div className="max-h-48 space-y-1 overflow-auto rounded-lg bg-zinc-950 p-2">{dashboard?.enforcementGaps?.map(item => <label key={item.playing_cycle_id} className="flex items-center gap-2 text-sm"><input type="checkbox" checked={foundingGrant.cycleIds.includes(item.playing_cycle_id)} onChange={event => setFoundingGrant(current => ({ ...current,cycleIds:event.target.checked?[...current.cycleIds,item.playing_cycle_id]:current.cycleIds.filter(id=>id!==item.playing_cycle_id),preview:null,operationId:'' }))}/>{item.team_name} / {item.name}</label>)}</div>}<div className="grid grid-cols-2 gap-2"><Sel label="Grant type" value={foundingGrant.state} onChange={event => setFoundingGrant({ ...foundingGrant,state:event.target.value,preview:null })}><option value="trial">Trial</option><option value="complimentary">Complimentary</option></Sel><Input label="Agreed price £" type="number" min="0" step="0.01" value={foundingGrant.agreedPricePounds} onChange={event => setFoundingGrant({ ...foundingGrant,agreedPricePounds:event.target.value,preview:null })}/><Input label="Starts" type="datetime-local" value={foundingGrant.validFrom} onChange={event => setFoundingGrant({ ...foundingGrant,validFrom:event.target.value,preview:null })}/><Input label="Ends" type="datetime-local" value={foundingGrant.validUntil} onChange={event => setFoundingGrant({ ...foundingGrant,validUntil:event.target.value,preview:null })}/><Input label="Discount £" type="number" min="0" step="0.01" value={foundingGrant.discountPounds} onChange={event => setFoundingGrant({ ...foundingGrant,discountPounds:event.target.value,preview:null })}/></div><Input label="Owner and detailed reason" value={foundingGrant.reason} onChange={event => setFoundingGrant({ ...foundingGrant,reason:event.target.value,preview:null })}/><div className="flex gap-2"><Btn size="sm" variant="outline" disabled={status.saving || (!foundingGrant.audienceId&&!foundingGrant.cycleIds.length) || !foundingGrant.validFrom || !foundingGrant.validUntil || foundingGrant.reason.trim().length<12} onClick={async()=>{const operationId=crypto.randomUUID();try{const input={...foundingGrant,operationId};const preview=foundingGrant.audienceId?await commercial.grantFoundingAudienceAccess(input,true):await commercial.grantFoundingAccessBatch(input,true);setFoundingGrant(current=>({...current,operationId,preview}))}catch(error){setStatus(current=>({...current,error:error?.message??'Grant preview failed.'}))}}}>Preview grant</Btn><Btn size="sm" variant="danger" disabled={status.saving || !foundingGrant.preview} onClick={()=>act(()=>foundingGrant.audienceId?commercial.grantFoundingAudienceAccess(foundingGrant,false):commercial.grantFoundingAccessBatch(foundingGrant,false),`${foundingGrant.preview?.affected?.length??0} founding access grants applied and audited.`)}>Confirm previewed grant</Btn></div>{foundingGrant.preview&&<p className="mt-2 rounded-lg border border-amber-800 bg-amber-950/30 p-2 text-xs text-amber-200">{foundingGrant.preview.audienceName&&<>{foundingGrant.preview.audienceName}: </>}{foundingGrant.preview.affected?.length??0} affected; {foundingGrant.preview.exclusions?.length??0} excluded. Owner is the approving administrator; agreed price and discount are immutable grant terms.</p>}
    </Card>
    <Card title="Founding pilot evaluation" hidden={activeSection !== 'pilots'}>
      <p className="mb-2 text-xs text-zinc-400">Capture the baseline before activation. Reports aggregate team/division/week adoption and never include fine descriptions.</p><div className="grid grid-cols-2 gap-2"><Input label="Pilot name" value={pilot.name} onChange={event=>setPilot({...pilot,name:event.target.value})}/><Input label="League name" value={pilot.leagueName} onChange={event=>setPilot({...pilot,leagueName:event.target.value})}/><Input label="Starts" type="date" value={pilot.startsOn} onChange={event=>setPilot({...pilot,startsOn:event.target.value})}/><Input label="Ends" type="date" value={pilot.endsOn} onChange={event=>setPilot({...pilot,endsOn:event.target.value})}/><Input label="Committee feedback" type="datetime-local" value={pilot.committeeFeedbackAt} onChange={event=>setPilot({...pilot,committeeFeedbackAt:event.target.value})}/><Input label="Captain group feedback" type="datetime-local" value={pilot.captainFeedbackAt} onChange={event=>setPilot({...pilot,captainFeedbackAt:event.target.value})}/></div><div className="mt-2 max-h-36 space-y-1 overflow-auto rounded-lg bg-zinc-950 p-2">{dashboard?.enforcementGaps?.map(item=><label key={item.playing_cycle_id} className="flex items-center gap-2 text-xs"><input type="checkbox" checked={pilot.cycleIds.includes(item.playing_cycle_id)} onChange={event=>setPilot(current=>({...current,cycleIds:event.target.checked?[...current.cycleIds,item.playing_cycle_id]:current.cycleIds.filter(id=>id!==item.playing_cycle_id)}))}/>{item.team_name} / {item.name}</label>)}</div><Input label="Creation reason" value={pilot.reason} onChange={event=>setPilot({...pilot,reason:event.target.value})}/><Btn size="sm" disabled={status.saving||pilot.name.length<4||pilot.leagueName.length<3||!pilot.cycleIds.length||!pilot.startsOn||!pilot.endsOn||!pilot.committeeFeedbackAt||!pilot.captainFeedbackAt||pilot.reason.trim().length<12} onClick={()=>act(()=>commercial.createCommercialPilot({playingCycleIds:pilot.cycleIds,name:pilot.name,leagueName:pilot.leagueName,startsOn:pilot.startsOn,endsOn:pilot.endsOn,committeeFeedbackAt:new Date(pilot.committeeFeedbackAt).toISOString(),captainFeedbackAt:new Date(pilot.captainFeedbackAt).toISOString(),successCriteria:{activatedTeams:true,matchesRecorded:true,activeMembers:true,captainTimeSaved:true,supportDemand:true,willingnessToRenew:true},divisions:{},captainSampleTeamIds:{}},pilot.reason),'Pilot baseline and feedback schedule recorded.')}>Create pilot baseline</Btn>
      {pilotDashboard.pilots.length>0&&<div className="mt-4 border-t border-zinc-800 pt-3"><Sel label="Pilot to complete" value={pilotOutcome.pilotId} onChange={event=>setPilotOutcome({...pilotOutcome,pilotId:event.target.value})}><option value="">Select pilot</option>{pilotDashboard.pilots.filter(item=>item.state!=='completed').map(item=><option key={item.id} value={item.id}>{item.name} ({item.state})</option>)}</Sel><Sel label="Renewal outcome" value={pilotOutcome.renewalOutcome} onChange={event=>setPilotOutcome({...pilotOutcome,renewalOutcome:event.target.value})}><option value="renewed">Renewed</option><option value="declined">Declined</option><option value="extended">Extended</option><option value="undecided">Undecided</option></Sel><Input label="Outcome reasons (comma separated)" value={pilotOutcome.renewalReasons} onChange={event=>setPilotOutcome({...pilotOutcome,renewalReasons:event.target.value})}/><Input label="Decision evidence reason" value={pilotOutcome.reason} onChange={event=>setPilotOutcome({...pilotOutcome,reason:event.target.value})}/><Btn size="sm" variant="danger" disabled={!pilotOutcome.pilotId||!pilotOutcome.renewalReasons.trim()||pilotOutcome.reason.trim().length<12} onClick={()=>act(()=>commercial.updateCommercialPilotEvaluation({pilotId:pilotOutcome.pilotId,state:'completed',renewalOutcome:pilotOutcome.renewalOutcome,renewalReasons:pilotOutcome.renewalReasons.split(',').map(value=>value.trim()).filter(Boolean),reason:pilotOutcome.reason}),'Pilot renewal outcome recorded and audited.')}>Complete pilot evaluation</Btn></div>}
      <div className="mt-3 space-y-2">{pilotDashboard.pilots.map(item=><div key={item.id} className="rounded-lg bg-zinc-800 p-2 text-xs"><strong>{item.name}</strong> · {item.state} · {item.starts_on} to {item.ends_on}<br/>Baseline: {item.baseline?.selectedTeams??0} teams, {item.baseline?.activeMembers??0} active members, {item.baseline?.existingMatches??0} existing matches.</div>)}</div>
    </Card>
    <Card title="Incident operations" hidden={activeSection !== 'service'}>
      <Input label="Incident title" value={incident.title} onChange={event => setIncident({ ...incident, title: event.target.value })}/><Sel label="Impact" value={incident.impact} onChange={event => setIncident({ ...incident, impact: event.target.value })}><option value="none">None</option><option value="minor">Minor</option><option value="major">Major</option><option value="critical">Critical</option></Sel><div className="grid grid-cols-2 gap-1 rounded-lg bg-zinc-950 p-2">{dashboard?.serviceComponents?.map(item=><label key={item.code} className="flex items-center gap-2 text-xs"><input type="checkbox" checked={incident.components.includes(item.code)} onChange={event=>setIncident(current=>({...current,components:event.target.checked?[...current.components,item.code]:current.components.filter(code=>code!==item.code)}))}/>{item.name}</label>)}</div><Input label="Public update" value={incident.message} onChange={event => setIncident({ ...incident, message: event.target.value })}/><Input label="Operator reason" value={incident.reason} onChange={event => setIncident({ ...incident, reason: event.target.value })}/><Btn size="sm" disabled={status.saving || incident.title.trim().length < 5 || !incident.components.length || incident.message.trim().length < 10 || incident.reason.trim().length < 8} onClick={() => act(() => commercial.createServiceIncident(incident), 'Public incident opened, audited and material notices queued.')}>Open incident</Btn>
      {incidentQueue.length>0&&<div className="mt-4 border-t border-zinc-800 pt-3"><Sel label="Open incident" value={incidentUpdate.incidentId} onChange={event=>setIncidentUpdate({...incidentUpdate,incidentId:event.target.value})}><option value="">Select incident</option>{incidentQueue.map(item=><option key={item.id} value={item.id}>{item.title} ({item.status})</option>)}</Sel><Sel label="New status" value={incidentUpdate.status} onChange={event=>setIncidentUpdate({...incidentUpdate,status:event.target.value})}><option value="investigating">Investigating</option><option value="identified">Identified</option><option value="monitoring">Monitoring</option><option value="resolved">Resolved</option></Sel><Input label="Public timeline update" value={incidentUpdate.message} onChange={event=>setIncidentUpdate({...incidentUpdate,message:event.target.value})}/><Input label="Mitigation" value={incidentUpdate.mitigation} onChange={event=>setIncidentUpdate({...incidentUpdate,mitigation:event.target.value})}/>{incidentUpdate.status==='resolved'&&<Input label="Post-incident actions (comma separated)" value={incidentUpdate.postIncidentActions} onChange={event=>setIncidentUpdate({...incidentUpdate,postIncidentActions:event.target.value})}/>}<label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={incidentUpdate.notifyAffected} onChange={event=>setIncidentUpdate({...incidentUpdate,notifyAffected:event.target.checked})}/>Notify active billing customers for a material incident</label><Input label="Update reason" value={incidentUpdate.reason} onChange={event=>setIncidentUpdate({...incidentUpdate,reason:event.target.value})}/><Btn size="sm" disabled={status.saving||!incidentUpdate.incidentId||incidentUpdate.message.trim().length<10||incidentUpdate.reason.trim().length<8||(incidentUpdate.status==='resolved'&&(!incidentUpdate.mitigation.trim()||!incidentUpdate.postIncidentActions.trim()))} onClick={()=>act(()=>commercial.updateServiceIncident(incidentUpdate),'Incident timeline updated, audited and approved notices queued.')}>Publish incident update</Btn></div>}
      <div className="mt-3 space-y-2">{dashboard?.serviceComponents?.map(item => <div key={item.code} className="flex items-center justify-between rounded-lg bg-zinc-800 p-2 text-sm"><span>{item.name}: {item.status}</span><Btn size="sm" variant="outline" disabled={status.saving || item.status === 'operational'} onClick={() => act(() => commercial.setServiceComponent(item.code, 'operational', 'Service operating normally', `Resolve ${item.name} component incident`), `${item.name} marked operational.`)}>Resolve</Btn></div>)}</div>
    </Card>
    <Card title="Accounting export" hidden={activeSection !== 'finance'}>
      <div className="grid grid-cols-2 gap-2"><Input label="From" type="date" value={exportPeriod.from} onChange={event => setExportPeriod({ ...exportPeriod, from: event.target.value })}/><Input label="To (exclusive)" type="date" value={exportPeriod.to} onChange={event => setExportPeriod({ ...exportPeriod, to: event.target.value })}/></div><Btn size="sm" variant="outline" disabled={!exportPeriod.from || !exportPeriod.to} onClick={async () => { try { const rows = await commercial.getAccountingExport(exportPeriod.from, exportPeriod.to); downloadAccountingCsv(rows, exportPeriod) } catch (error) { setStatus(current => ({ ...current, error: error?.message ?? 'Accounting export failed.' })) } }}>Download CSV</Btn>
    </Card>
    <Card title="High-risk billing recovery" hidden={activeSection !== 'finance'}>
      <p className="text-xs text-zinc-400">Use only when the previous billing owner is unavailable. A second platform administrator must approve; provider customer, invoices, subscriptions and entitlements are preserved.</p><Input label="Billing customer ID" value={recovery.billingCustomerId} onChange={event => setRecovery({ ...recovery,billingCustomerId:event.target.value })}/><Input label="Verified replacement email" type="email" value={recovery.email} onChange={event => setRecovery({ ...recovery,email:event.target.value })}/><Input label="Evidence reference (no secrets)" value={recovery.evidenceReference} onChange={event => setRecovery({ ...recovery,evidenceReference:event.target.value })}/><Input label="Detailed recovery reason" value={recovery.reason} onChange={event => setRecovery({ ...recovery,reason:event.target.value })}/><Btn size="sm" variant="danger" disabled={status.saving || !recovery.billingCustomerId || !recovery.email || recovery.evidenceReference.trim().length < 8 || recovery.reason.trim().length < 12} onClick={() => act(() => commercial.createBillingRecoveryRequest(recovery),'Recovery request recorded for independent approval.')}>Request recovery</Btn>
      {recoveries.map(item => <div key={item.id} className="mt-3 rounded-lg border border-red-900 bg-red-950/30 p-3"><p className="text-sm font-bold">{item.teamName ?? item.billingCustomerId}</p><p className="text-xs text-zinc-400">Evidence: {item.evidenceReference} · expires {new Date(item.expiresAt).toLocaleString('en-GB')}</p><Input label="Independent approval reason" value={recovery.approvalReason} onChange={event => setRecovery({ ...recovery,approvalReason:event.target.value })}/><Btn size="sm" variant="danger" disabled={status.saving || recovery.approvalReason.trim().length < 12} onClick={() => act(() => commercial.approveBillingRecoveryRequest(item.id,recovery.approvalReason),'High-risk billing recovery approved and audited.')}>Approve as second administrator</Btn></div>)}
    </Card>
    <Card title="Support queue" hidden={activeSection !== 'support'}>
      {supportCases.length === 0 ? <p className="text-sm text-zinc-400">No open cases.</p> : <div className="space-y-3">{supportCases.slice(0, 20).map(item => <SupportCase key={item.id} item={item} saving={status.saving} onUpdate={input => act(() => commercial.updateSupportCase(input), `Support case ${item.reference} updated.`)}/>)}</div>}
    </Card>
  </div>
}

function SupportCase({ item, saving, onUpdate }) {
  const [form, setForm] = useState({ status: item.status, priority: item.priority, customerMessage: '', internalNote: '', reason: 'Support case triage update' })
  return <div className="rounded-xl border border-zinc-800 bg-zinc-950 p-3"><div className="flex items-start justify-between gap-2"><div><p className="font-bold text-white">{item.reference}: {item.subject}</p><p className="text-xs text-zinc-400">{item.case_type} · {item.contact_email}</p></div><Badge color={item.priority === 'urgent' ? 'red' : item.priority === 'high' ? 'amber' : 'gray'}>{item.priority}</Badge></div><p className="mt-2 text-sm text-zinc-300">{item.description}</p><div className="mt-3 grid grid-cols-2 gap-2"><Sel label="State" value={form.status} onChange={event => setForm({ ...form, status: event.target.value })}><option value="open">Open</option><option value="acknowledged">Acknowledged</option><option value="waiting_customer">Waiting customer</option><option value="resolved">Resolved</option><option value="closed">Closed</option></Sel><Sel label="Priority" value={form.priority} onChange={event => setForm({ ...form, priority: event.target.value })}><option value="low">Low</option><option value="normal">Normal</option><option value="high">High</option><option value="urgent">Urgent</option></Sel></div><Input label="Customer-visible update (optional)" value={form.customerMessage} onChange={event => setForm({ ...form, customerMessage: event.target.value })}/><Input label="Internal note (optional)" value={form.internalNote} onChange={event => setForm({ ...form, internalNote: event.target.value })}/><Btn size="sm" disabled={saving || form.reason.trim().length < 8} onClick={() => onUpdate({ caseId: item.id, ...form })}>Update case</Btn></div>
}

function downloadAccountingCsv(rows, period) {
  const headers = ['occurredAt','provider','providerReference','entryType','currency','grossAmountMinor','discountAmountMinor','taxAmountMinor','processorFeeMinor','netAmountMinor','receiptUrl','subscriptionId']
  const escape = value => `"${String(value ?? '').replaceAll('"','""')}"`
  const csv = [headers.join(','), ...rows.map(row => headers.map(key => escape(row[key])).join(','))].join('\n')
  const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' }))
  const link = document.createElement('a'); link.href = url; link.download = `roobin-commercial-${period.from}-${period.to}.csv`; link.click(); URL.revokeObjectURL(url)
}
